pub type AppError = Failed(String)

byres record FileHandle { fd: Int64 }

impl Releasable for FileHandle {
    fn release(mut self) {
        return
    }
}

impl FileHandle {
    fn bump(mut self) -> Int64 {
        return 1
    }
}

fn openFile() -> FileHandle {
    return FileHandle { fd: 1 }
}

pub fn main() effect net -> Result<(), AppError> {
    scope resource(f = openFile()) {
